/* ---------- geradores próprios de Português ---------- */
/* divisão silábica: as erradas deslocam uma fronteira de sílaba */
function sepWrongs(w){ const parts=w.split('-'),out=new Set();
  for(let i=0;i<parts.length-1;i++){ const a=parts[i],b=parts[i+1];
    if(a.length>1){ const p=parts.slice(); p[i]=a.slice(0,-1); p[i+1]=a.slice(-1)+b; out.add(p.join('-')); }
    if(b.length>1){ const p=parts.slice(); p[i]=a+b[0]; p[i+1]=b.slice(1); out.add(p.join('-')); } }
  out.add(parts.join('')); out.delete(w); return shuffle([...out]); }
const SEP=['car-ro','pás-sa-ro','pa-ís','sa-í-da','sa-ú-de','ra-i-nha','ca-der-no','ex-ce-ção','nas-cer','cres-cer','ex-ces-so','ad-vo-ga-do','rit-mo','psi-có-lo-go','e-nig-ma','gno-mo','sub-ma-ri-no','guer-ra','quei-jo','Pa-ra-guai','sa-guão','co-o-pe-rar','vo-o','mei-o','i-dei-a','ap-to','fic-ção','cai-xa','mos-qui-to','pers-pi-caz','ab-dô-men','of-tal-mo-lo-gis-ta','ma-ni-a','ju-iz','tran-qui-lo','sos-se-go','des-cer'];
const SEPX={'car-ro':'Dígrafo <b>rr</b> se separa.','pás-sa-ro':'Dígrafo <b>ss</b> se separa.','pa-ís':'Hiato (a-í): vogais em sílabas diferentes.','sa-í-da':'Hiato a-í.','sa-ú-de':'Hiato a-ú.','ra-i-nha':'Hiato a-i; <b>nh</b> não se separa.','ex-ce-ção':'Dígrafo <b>xc</b> se separa.','nas-cer':'Dígrafo <b>sc</b> se separa.','cres-cer':'Dígrafo <b>sc</b> se separa.','ex-ces-so':'<b>xc</b> e <b>ss</b> se separam.','ad-vo-ga-do':'Consoante muda sem vogal fica na sílaba anterior: <b>ad</b>-vo.','rit-mo':'Encontro consonantal separável: <b>t-m</b>.','psi-có-lo-go':'<b>ps</b> no início da palavra não se separa.','e-nig-ma':'<b>g-m</b> no meio da palavra se separa.','gno-mo':'<b>gn</b> no início da palavra não se separa.','sub-ma-ri-no':'Prefixo sub + consoante: sub-ma.','guer-ra':'<b>gu</b> é dígrafo (não se separa); <b>rr</b> se separa.','quei-jo':'<b>qu</b> é dígrafo e <b>ei</b> é ditongo: não se separam.','Pa-ra-guai':'Tritongo <b>uai</b> fica na mesma sílaba.','sa-guão':'Tritongo <b>uão</b> não se separa.','co-o-pe-rar':'Hiato <b>o-o</b>.','vo-o':'Hiato <b>o-o</b> (sem acento desde o Acordo de 2009).','mei-o':'Ditongo <b>ei</b> + vogal <b>o</b> em outra sílaba.','i-dei-a':'Ditongo <b>ei</b> (sem acento desde o Acordo de 2009).','ap-to':'Consoante muda <b>p</b> fica com a sílaba anterior.','fic-ção':'<b>c-ç</b> se separam.','cai-xa':'Ditongo <b>ai</b> não se separa.','mos-qui-to':'<b>qu</b> é dígrafo.','pers-pi-caz':'<b>rs</b> + consoante: pers-pi.','ab-dô-men':'Consoante muda <b>b</b> fica na sílaba anterior.','of-tal-mo-lo-gis-ta':'<b>f-t</b> e <b>l-m</b> se separam.','ma-ni-a':'Hiato <b>i-a</b>.','ju-iz':'Hiato <b>u-i</b>.','tran-qui-lo':'<b>qu</b> é dígrafo; <b>n</b> fecha a sílaba tran.','sos-se-go':'Dígrafo <b>ss</b> se separa.','des-cer':'Dígrafo <b>sc</b> se separa.'};
const sepGen=lv=>{ const w=pick(SEP); return MC(`Qual é a divisão silábica correta de <b>${w.replace(/-/g,'')}</b>?`,w,sepWrongs(w),`<b>${w}</b>. ${SEPX[w]||''}`,'Separe dígrafos rr, ss, sc, xc; não separe ch, lh, nh, qu, gu, ditongos e tritongos; separe hiatos.'); };
/* tonicidade */
const TON=[['café','oxítona'],['jacaré','oxítona'],['parabéns','oxítona'],['sofá','oxítona'],['você','oxítona'],['amor','oxítona'],['papel','oxítona'],['urubu','oxítona'],['ninguém','oxítona'],['Paraná','oxítona'],['ruim','oxítona','ru-IM: a tônica é a última sílaba.'],['Nobel','oxítona','no-BEL.'],['casa','paroxítona'],['lápis','paroxítona'],['fácil','paroxítona'],['açúcar','paroxítona'],['táxi','paroxítona'],['caráter','paroxítona'],['hífen','paroxítona'],['vírus','paroxítona'],['júri','paroxítona'],['ideia','paroxítona'],['órfão','paroxítona'],['rubrica','paroxítona','ru-BRI-ca (e não "rúbrica").'],['recorde','paroxítona','re-COR-de.'],['gratuito','paroxítona','gra-TUI-to.'],['lâmpada','proparoxítona'],['pássaro','proparoxítona'],['médico','proparoxítona'],['árvore','proparoxítona'],['música','proparoxítona'],['fósforo','proparoxítona'],['sílaba','proparoxítona'],['relâmpago','proparoxítona'],['ônibus','proparoxítona'],['xícara','proparoxítona'],['pêssego','proparoxítona'],['matemática','proparoxítona']];
const tonGen=lv=>{ const [w,c,x]=pick(TON); return MC(`Quanto à posição da sílaba tônica, a palavra <b>${w}</b> é:`,c,['oxítona','paroxítona','proparoxítona'].filter(v=>v!==c),`<b>${w}</b> é <b>${c}</b>. ${x||(c==='oxítona'?'A tônica é a última sílaba.':c==='paroxítona'?'A tônica é a penúltima sílaba.':'A tônica é a antepenúltima sílaba.')}`,'Leia em voz alta e veja qual sílaba é mais forte: última (oxítona), penúltima (paroxítona) ou antepenúltima (proparoxítona).',{keep:true}); };
/* conjugação de verbos regulares */
const VERBS=[['cantar','cant','ar'],['falar','fal','ar'],['estudar','estud','ar'],['andar','and','ar'],['trabalhar','trabalh','ar'],['amar','am','ar'],['vender','vend','er'],['beber','beb','er'],['comer','com','er'],['correr','corr','er'],['aprender','aprend','er'],['partir','part','ir'],['dividir','divid','ir'],['decidir','decid','ir'],['assistir','assist','ir'],['discutir','discut','ir'],['permitir','permit','ir']];
const TENSES={
 'presente do indicativo':{ar:['o','as','a','amos','ais','am'],er:['o','es','e','emos','eis','em'],ir:['o','es','e','imos','is','em']},
 'pretérito perfeito do indicativo':{ar:['ei','aste','ou','amos','astes','aram'],er:['i','este','eu','emos','estes','eram'],ir:['i','iste','iu','imos','istes','iram']},
 'pretérito imperfeito do indicativo':{ar:['ava','avas','ava','ávamos','áveis','avam'],er:['ia','ias','ia','íamos','íeis','iam'],ir:['ia','ias','ia','íamos','íeis','iam']},
 'futuro do presente do indicativo':{ar:['arei','arás','ará','aremos','areis','arão'],er:['erei','erás','erá','eremos','ereis','erão'],ir:['irei','irás','irá','iremos','ireis','irão']},
 'futuro do pretérito do indicativo':{ar:['aria','arias','aria','aríamos','aríeis','ariam'],er:['eria','erias','eria','eríamos','eríeis','eriam'],ir:['iria','irias','iria','iríamos','iríeis','iriam']},
 'presente do subjuntivo':{ar:['e','es','e','emos','eis','em'],er:['a','as','a','amos','ais','am'],ir:['a','as','a','amos','ais','am']}};
const PESS=['eu','tu','ele/ela','nós','vós','eles/elas'],PESSN=['1ª pessoa do singular (eu)','2ª pessoa do singular (tu)','3ª pessoa do singular (ele/ela)','1ª pessoa do plural (nós)','2ª pessoa do plural (vós)','3ª pessoa do plural (eles/elas)'];
const conj=(v,t,p)=>v[1]+TENSES[t][v[2]][p];
const conjGens=[
 lv=>{ const v=pick(VERBS),t=pick(Object.keys(TENSES)),p=pick([0,2,3,5]); const c=conj(v,t,p);
   return MC(`Qual é a forma do verbo <b>${v[0]}</b> na <b>${PESSN[p]}</b> do <b>${t}</b>?`,c,Object.keys(TENSES).filter(x=>x!==t).map(x=>conj(v,x,p)),`${PESS[p]} <b>${c}</b> (${t}). Verbo regular da ${v[2]==='ar'?'1ª':v[2]==='er'?'2ª':'3ª'} conjugação (-${v[2]}).`,'Tire a terminação -ar/-er/-ir e acrescente a desinência do tempo pedido.'); },
 lv=>{ let v,t,p,c,tries=0; do{ v=pick(VERBS); t=pick(Object.keys(TENSES)); p=pick([0,2,3,5]); c=conj(v,t,p); tries++; }while(tries<20&&Object.keys(TENSES).some(x=>x!==t&&conj(v,x,p)===c));
   return MC(`Em que tempo e modo está a forma verbal <b>${c}</b> (verbo ${v[0]})?`,t,Object.keys(TENSES).filter(x=>x!==t),`<b>${c}</b>: ${PESS[p]}, ${t}.`,'Compare as terminações: -ava/-ia (imperfeito), -ei/-i (perfeito), -rei (futuro), -ria (futuro do pretérito).'); },
 lv=>{ const v=pick(VERBS),p=pick([0,2,3,5]); const frames=[['Ontem','pretérito perfeito do indicativo'],['Amanhã','futuro do presente do indicativo'],['Antigamente,','pretérito imperfeito do indicativo'],['Todos os dias','presente do indicativo']]; const [adv,t]=pick(frames); const c=conj(v,t,p);
   const subj=['eu','—','ela','nós','—','eles'][p];
   return BANK('Complete com a forma verbal adequada',`${adv} ${subj} @@ (${v[0]}).`,c,Object.keys(TENSES).filter(x=>x!==t).map(x=>conj(v,x,p)),`"${adv}" pede o <b>${t}</b>: ${subj} <b>${c}</b>.`,'O advérbio de tempo indica se a ação é passada, presente ou futura.'); }];

