UNITS.push({id:'p1',title:'Sons, sílabas e escrita',sub:'Fundamental · divisão silábica, acentuação, ortografia e pontuação',color:'#ce82ff',dark:'#a568cc',skills:[
SKL('silaba','Sílabas e divisão silábica','✂️','Separe dígrafos rr, ss, sc, sç, xc e hiatos; nunca separe ch, lh, nh, qu, gu, ditongos e tritongos.',
`<p><b>Sílaba</b> é cada impulso de voz ao pronunciar uma palavra. Toda sílaba tem uma <b>vogal</b>.</p>
<h3>Encontros vocálicos</h3><ul><li><b>Ditongo</b>: vogal + semivogal na mesma sílaba (<i>cai-xa, mei-o</i>).</li><li><b>Tritongo</b>: semivogal + vogal + semivogal (<i>Pa-ra-<b>guai</b>, sa-<b>guão</b></i>).</li><li><b>Hiato</b>: vogais em sílabas diferentes (<i>sa-<b>ú</b>-de, vo-o</i>).</li></ul>
<h3>Dígrafos</h3><p>Duas letras e um só som. <b>Separam-se</b>: rr, ss, sc, sç, xc (<i>car-ro, nas-cer, ex-ce-ção</i>). <b>Não se separam</b>: ch, lh, nh, qu, gu (<i>fi-lho, quei-jo</i>).</p>
<div class="ex">Consoante sem vogal no meio da palavra fica com a sílaba anterior: <b>ad</b>-vo-ga-do, <b>ap</b>-to, <b>rit</b>-mo. No início, fica com a seguinte: <b>psi</b>-có-lo-go, <b>gno</b>-mo.</div>`,
{gens:[sepGen,sepGen],pairs:[['Ditongo','encontro de vogal e semivogal na mesma sílaba, como em "cai-xa"'],['Tritongo','semivogal + vogal + semivogal na mesma sílaba, como em "Pa-ra-guai"'],['Hiato','vogais vizinhas em sílabas diferentes, como em "sa-ú-de"'],['Dígrafo','duas letras que representam um só som, como "ch" e "rr"'],['Encontro consonantal','duas consoantes com sons distintos, como "bl" em "bloco"'],['Monossílabo','palavra de uma só sílaba, como "mar"']],
 tf:[['Na divisão silábica, o dígrafo "rr" fica na mesma sílaba.',false,'Falso: rr, ss, sc, sç e xc se separam (car-ro).'],['Em "quei-jo", "qu" é dígrafo e não se separa.',true,'Verdadeiro.'],['"Saúde" tem hiato.',true,'Verdadeiro: sa-ú-de.'],['"Psicólogo" separa-se "p-si-có-lo-go".',false,'Falso: ps no início fica junto: psi-có-lo-go.']]}),
SKL('acento','Tonicidade e acentuação','✒️','Toda proparoxítona é acentuada. Oxítonas: acentue as terminadas em a(s), e(s), o(s), em(ens).',
`<p>Pela posição da sílaba tônica: <b>oxítona</b> (última: ca-<b>fé</b>), <b>paroxítona</b> (penúltima: <b>me</b>-sa), <b>proparoxítona</b> (antepenúltima: <b>lâm</b>-pa-da).</p>
<h3>Regras principais</h3><ul><li><b>Proparoxítonas</b>: todas são acentuadas (<i>música, pássaro</i>).</li><li><b>Oxítonas</b>: terminadas em <b>a(s), e(s), o(s), em, ens</b> (<i>sofá, café, avô, ninguém, parabéns</i>).</li><li><b>Paroxítonas</b>: terminadas em <b>l, n, r, x, ps, ã(s), ão(s), i(s), us, um, uns, ditongo oral</b> (<i>fácil, hífen, açúcar, tórax, bíceps, órfã, órgão, táxi, vírus, álbum, história</i>). As terminadas em a, e, o, em <b>não</b> levam acento (<i>casa, item</i>).</li><li><b>Monossílabos tônicos</b> em a(s), e(s), o(s): <i>pá, pé, nó</i>.</li></ul>
<h3>Acordo Ortográfico (2009)</h3><ul><li>Caiu o acento dos ditongos abertos <b>ei, oi</b> em paroxítonas: <i>ideia, heroico, assembleia</i> (mas <i>herói, papéis</i> — oxítonas — mantêm).</li><li>Caiu o acento de <b>oo</b> e <b>ee</b>: <i>voo, enjoo, leem, creem</i>.</li><li>Caiu o <b>trema</b>: <i>linguiça, frequente</i>.</li><li>Caíram os diferenciais de <i>para</i> (verbo), <i>pelo, polo</i>. Ficaram <b>pôr</b> (verbo) e <b>pôde</b> (passado).</li></ul>`,
{gens:[tonGen,tonGen],qs:[['Qual palavra está acentuada <b>incorretamente</b>, segundo o Acordo Ortográfico?','idéia',['herói','café','ônibus'],'Desde 2009, paroxítonas com ditongo aberto "ei" não levam acento: <b>ideia</b>. "Herói" é oxítona e mantém.'],['Por que "táxi" leva acento?','É paroxítona terminada em i',['É oxítona terminada em i','É proparoxítona','Todo x exige acento'],'Paroxítonas terminadas em <b>i(s)</b> são acentuadas: táxi, júri, lápis.'],['Por que "café" leva acento?','É oxítona terminada em e',['É paroxítona terminada em e','É proparoxítona','É monossílabo tônico'],'Oxítonas terminadas em a(s), e(s), o(s), em, ens são acentuadas.'],['Qual palavra NÃO deveria ter acento?','heróico',['herói','lâmpada','fácil'],'"Heroico" é paroxítona com ditongo aberto oi: perdeu o acento no Acordo de 2009. "Herói" (oxítona) mantém.'],['Qual é a grafia correta, segundo o Acordo?','voo',['vôo','voô','vóo'],'Caiu o acento circunflexo do hiato "oo": voo, enjoo.'],['"Ele ___ ir ontem, mas hoje não pode." Complete:','pôde',['pode','pôdi','podê'],'<b>Pôde</b> (pretérito) mantém o acento diferencial em relação a <b>pode</b> (presente).'],['Qual palavra está grafada corretamente?','linguiça',['lingüiça','linguíça','lingüíça'],'O trema foi abolido: linguiça, frequente, cinquenta.']],
 tf:[['Toda proparoxítona é acentuada.',true,'Verdadeiro: lâmpada, pássaro, médico.'],['"Item" leva acento por ser paroxítona terminada em -em.',false,'Falso: paroxítonas terminadas em -em não são acentuadas (item, hífen é que tem -en).'],['"Pôr" (verbo) mantém o acento diferencial.',true,'Verdadeiro: pôr (verbo) × por (preposição).'],['"Ideia" continua com acento agudo após o Acordo.',false,'Falso: ideia, assembleia, heroico perderam o acento.']]}),
SKL('ortog','Ortografia','🔤','Na dúvida entre letras, pense na família da palavra: casa → casinha, caseiro (com s).',
`<p>Muitos erros vêm de letras com o mesmo som. Dicas que resolvem a maioria dos casos:</p>
<ul><li><b>X</b> depois de ditongo (<i>caixa, peixe</i>), depois de <i>en-</i> (<i>enxada, enxergar</i>) e depois de <i>me-</i> (<i>mexer, mexerica</i>). Exceção: <i>encher</i> (de cheio), <i>mecha</i>.</li><li><b>-ês / -esa</b> em origem e títulos (<i>português, francesa, princesa</i>); <b>-ez / -eza</b> em substantivos abstratos de adjetivos (<i>rapidez, beleza</i>).</li><li><b>-isar</b> quando a palavra já tem s (<i>análise → analisar, pesquisa → pesquisar</i>); <b>-izar</b> nos demais (<i>real → realizar</i>).</li><li><b>Ç</b> nunca antes de e ou i e nunca no início de palavra.</li><li><b>G/J</b>: <i>-agem</i> com g (<i>viagem</i>, substantivo), mas <i>viajem</i> (verbo) com j; palavras de origem tupi e africana com j (<i>jiboia, jiló, canjica</i>).</li></ul>
<h3>Porquês</h3><ul><li><b>por que</b>: pergunta ou "pelo qual" (<i>Por que você saiu?</i>)</li><li><b>por quê</b>: no fim da frase (<i>Você saiu por quê?</i>)</li><li><b>porque</b>: explicação/causa (<i>Saí porque choveu.</i>)</li><li><b>porquê</b>: substantivo, com artigo (<i>Não sei o porquê.</i>)</li></ul>
<h3>Parecidas</h3><p><b>mas</b> (porém) × <b>mais</b> (quantidade); <b>mal</b> (oposto de bem) × <b>mau</b> (oposto de bom); <b>há</b> (tempo passado) × <b>a</b> (tempo futuro/distância): "Saí há dois dias; volto daqui a dois dias".</p>`,
{bank:[['@@ você não veio à festa?','Por que',['Porque','Por quê','Porquê'],'Pergunta direta no início: <b>por que</b>.'],['Não fui à aula @@ estava doente.','porque',['por que','por quê','porquê'],'Explicação/causa: <b>porque</b>.'],['Você chegou atrasado @@?','por quê',['porque','por que','porquê'],'No fim da frase: <b>por quê</b>.'],['Ninguém entendeu o @@ da decisão.','porquê',['porque','por que','por quê'],'Com artigo ("o porquê") é substantivo: <b>porquê</b>.'],['Estudou muito, @@ não passou.','mas',['mais','más','mais que'],'Ideia de oposição (porém): <b>mas</b>.'],['Ele é um @@ aluno.','mau',['mal','máu','mals'],'Oposto de <b>bom</b>: <b>mau</b> (adjetivo).'],['Ela dormiu @@ esta noite.','mal',['mau','máu','mals'],'Oposto de <b>bem</b>: <b>mal</b> (advérbio).'],['Moro aqui @@ dez anos.','há',['a','à','ah'],'Tempo passado: <b>há</b> (= faz).'],['A prova será daqui @@ dois dias.','a',['há','à','ha'],'Tempo futuro: <b>a</b>.'],['Precisamos @@ a sala para a reunião.','analisar',['analizar','annalisar','analisár'],'Vem de análi<b>s</b>e: anali<b>s</b>ar.'],['A @@ foi longa e cansativa.','viagem',['viajem','viájem','viagen'],'Substantivo: via<b>g</b>em. (Verbo: que eles via<b>j</b>em.)'],['Ele colocou o peixe na @@.','caixa',['caicha','cáixa','caisha'],'Depois de ditongo usa-se <b>x</b>: caixa, peixe.'],['Vou @@ o balde de água.','encher',['enxer','inxer','incher'],'Exceção: <b>encher</b> vem de "cheio".'],['A @@ dele impressionou a todos.','rapidez',['rapidês','rapides','rapideza'],'Substantivo abstrato derivado de adjetivo: -ez (rápido → rapidez).'],['Ela é @@ e mora em Lisboa.','portuguesa',['portugueza','portugêsa','portugesa'],'Origem: -ês/-esa (português, portuguesa).']]}),
SKL('pontua','Pontuação','❗','Não se separa sujeito e verbo com vírgula. Use vírgula para isolar vocativo, aposto, adjunto adverbial deslocado e itens de uma enumeração.',
`<h3>Vírgula: quando usar</h3><ul><li>Separar itens de enumeração: <i>Comprei arroz, feijão e óleo.</i></li><li>Isolar o <b>vocativo</b>: <i>Maria, venha cá.</i></li><li>Isolar o <b>aposto</b>: <i>Pedro, meu vizinho, é médico.</i></li><li>Isolar <b>adjunto adverbial deslocado</b> (sobretudo longo): <i>Na manhã seguinte, saímos cedo.</i></li><li>Antes de conjunções adversativas: <i>Estudei, mas não passei.</i></li><li>Isolar orações explicativas: <i>O homem, que é mortal, erra.</i></li><li>Indicar omissão de verbo (zeugma): <i>Eu prefiro café; ela, chá.</i></li></ul>
<h3>Quando NÃO usar</h3><p>Entre <b>sujeito e verbo</b> e entre <b>verbo e complemento</b>: <s>Os alunos, fizeram a prova.</s> → <i>Os alunos fizeram a prova.</i></p>
<h3>Outros sinais</h3><p><b>Ponto e vírgula</b> separa partes longas ou já com vírgulas; <b>dois-pontos</b> anunciam citação, enumeração ou explicação; <b>travessão</b> marca fala ou destaque; <b>reticências</b> indicam interrupção ou hesitação.</p>`,
{qs:[['Qual frase está pontuada corretamente?','Os alunos da turma B fizeram a prova.',['Os alunos da turma B, fizeram a prova.','Os alunos, da turma B fizeram, a prova.','Os alunos da turma B fizeram, a prova.'],'Não se separa o sujeito do verbo nem o verbo do complemento.'],['Em "Carlos, traga o livro", a vírgula isola:','o vocativo',['o aposto','o sujeito','o adjunto adverbial'],'"Carlos" é quem está sendo chamado: <b>vocativo</b>.'],['Em "Brasília, a capital do Brasil, foi inaugurada em 1960", o trecho entre vírgulas é:','um aposto',['um vocativo','o sujeito','um adjunto adverbial'],'O <b>aposto</b> explica um termo anterior e vem isolado por vírgulas.'],['Qual frase usa a vírgula para indicar a omissão de um verbo?','Eu gosto de café; ela, de chá.',['Eu gosto de café e ela de chá, também.','Eu, gosto de café.','Gosto, de café e de chá.'],'A vírgula marca o verbo omitido "gosta": zeugma.'],['A diferença de sentido entre "Os alunos que estudaram passaram" e "Os alunos, que estudaram, passaram" é que:','na segunda, todos os alunos estudaram',['na primeira, todos os alunos estudaram','não há diferença','a segunda está errada'],'Sem vírgulas a oração <b>restringe</b> (só os que estudaram passaram); com vírgulas ela <b>explica</b> (todos estudaram).'],['"Não, quero sair." e "Não quero sair." diferem porque:','na primeira a pessoa quer sair',['as duas negam a vontade de sair','a segunda está errada','a vírgula não muda o sentido'],'A vírgula separa a resposta "Não" da afirmação "quero sair".']],
 tf:[['É correto usar vírgula entre o sujeito e o verbo: "O diretor, falou."',false,'Falso: não se separa sujeito e verbo com vírgula.'],['A vírgula antes de "mas" é recomendada.',true,'Verdadeiro: conjunção adversativa vem precedida de vírgula.'],['Dois-pontos podem introduzir uma enumeração.',true,'Verdadeiro: "Levei três coisas: caneta, lápis e borracha."']]})
]});

/* ------------------------ UNIDADE 2 — CLASSES DE PALAVRAS ------------------------ */
UNITS.push({id:'p2',title:'Classes de palavras',sub:'Substantivo, adjetivo, verbo, pronome, advérbio, preposição e conjunção',color:'#1cb0f6',dark:'#1899d6',skills:[
SKL('subst','Substantivo e adjetivo','🏷️','Substantivo nomeia seres; adjetivo caracteriza o substantivo. Coletivo é o substantivo que indica um conjunto.',
`<p><b>Substantivo</b> dá nome a seres, objetos, lugares, sentimentos e ações (<i>casa, Brasil, alegria</i>).</p>
<ul><li><b>Comum</b> × <b>próprio</b>: cidade × Recife.</li><li><b>Concreto</b> (existe por si: mesa, fada) × <b>abstrato</b> (depende de outro ser: amor, beleza, corrida).</li><li><b>Coletivo</b>: indica conjunto (<i>cardume, alcateia</i>).</li><li><b>Primitivo</b> × <b>derivado</b>: pedra × pedreiro; <b>simples</b> × <b>composto</b>: couve × couve-flor.</li></ul>
<p><b>Adjetivo</b> atribui qualidade ou estado ao substantivo (<i>casa <b>grande</b></i>). <b>Locução adjetiva</b>: expressão com valor de adjetivo (<i>amor <b>de mãe</b></i> = materno).</p>
<h3>Grau do adjetivo</h3><p>Comparativo (<i>mais alto que</i>) e superlativo: relativo (<i>o mais alto</i>) ou absoluto (<i>altíssimo, muito alto</i>). Formas eruditas: <i>facílimo, paupérrimo, dulcíssimo, amicíssimo</i>.</p>`,
{pairs:[['Alcateia','conjunto de lobos'],['Cardume','conjunto de peixes'],['Enxame','conjunto de abelhas'],['Matilha','conjunto de cães'],['Constelação','conjunto de estrelas'],['Arquipélago','conjunto de ilhas'],['Biblioteca','coleção de livros'],['Resma','conjunto de 500 folhas de papel'],['Elenco','conjunto de atores de uma peça ou filme'],['Pinacoteca','coleção de quadros'],['Cordilheira','conjunto de montanhas'],['Esquadrilha','conjunto de aviões'],['Vara','conjunto de porcos'],['Fauna','conjunto dos animais de uma região'],['Flora','conjunto dos vegetais de uma região']],tq:t=>`O coletivo <b>${t}</b> designa:`,dq:d=>`Qual é o coletivo de: <b>${d}</b>?`,
 qs:[['Qual palavra é um substantivo <b>abstrato</b>?','saudade',['cadeira','fada','Recife'],'Abstrato nomeia sentimentos, estados, ações e qualidades: <b>saudade</b>.'],['Em "amor de mãe", a locução "de mãe" equivale ao adjetivo:','materno',['maternal e paterno','fraterno','filial'],'"De mãe" = <b>materno</b> (de pai = paterno; de irmão = fraterno).'],['O superlativo absoluto sintético erudito de "fácil" é:','facílimo',['facilíssimo','mais fácil','muito fácil'],'Forma erudita: <b>facílimo</b> (difícil → dificílimo).'],['Em "O menino estava feliz", a palavra "feliz" é:','adjetivo',['substantivo','advérbio','verbo'],'Atribui um estado ao substantivo "menino": <b>adjetivo</b>.'],['Qual é o superlativo absoluto sintético erudito de "pobre"?','paupérrimo',['pobríssimo','pobrérrimo','muito pobre'],'Forma erudita: <b>paupérrimo</b> (a forma popular é pobríssimo).']]}),
SKL('verbo','Verbos: tempos e modos','⏱️','Tire a terminação -ar, -er, -ir e acrescente a desinência do tempo: -ava/-ia (imperfeito), -ei/-i (perfeito), -rei (futuro).',
`<p><b>Verbo</b> indica ação, estado ou fenômeno e varia em <b>pessoa, número, tempo e modo</b>.</p>
<ul><li><b>Indicativo</b>: certeza (<i>canto, cantei, cantarei</i>).</li><li><b>Subjuntivo</b>: dúvida, desejo, hipótese (<i>que eu cante, se eu cantasse, quando eu cantar</i>).</li><li><b>Imperativo</b>: ordem ou pedido (<i>cante!</i>).</li></ul>
<h3>Conjugações</h3><p>1ª (-ar: cantar), 2ª (-er: vender; <i>pôr</i> também pertence à 2ª), 3ª (-ir: partir).</p>
<table><tr><th>Tempo (eu / nós)</th><th>cantar</th><th>vender</th><th>partir</th></tr><tr><td>Presente</td><td>canto / cantamos</td><td>vendo / vendemos</td><td>parto / partimos</td></tr><tr><td>Pret. perfeito</td><td>cantei / cantamos</td><td>vendi / vendemos</td><td>parti / partimos</td></tr><tr><td>Pret. imperfeito</td><td>cantava / cantávamos</td><td>vendia / vendíamos</td><td>partia / partíamos</td></tr><tr><td>Futuro do presente</td><td>cantarei / cantaremos</td><td>venderei / venderemos</td><td>partirei / partiremos</td></tr><tr><td>Futuro do pretérito</td><td>cantaria / cantaríamos</td><td>venderia / venderíamos</td><td>partiria / partiríamos</td></tr></table>
<h3>Formas nominais</h3><p>Infinitivo (<i>cantar</i>), gerúndio (<i>cantando</i>) e particípio (<i>cantado</i>).</p>`,
{gens:conjGens,qs:[['Em "Se eu estudasse, passaria", os verbos estão, respectivamente, no:','pretérito imperfeito do subjuntivo e futuro do pretérito do indicativo',['presente do subjuntivo e futuro do presente','pretérito perfeito e presente','imperativo e infinitivo'],'"Estudasse": hipótese no <b>imperfeito do subjuntivo</b>; "passaria": consequência no <b>futuro do pretérito</b>.'],['Qual forma está no modo imperativo?','Feche a porta!',['Eu fecho a porta.','Se eu fechasse a porta…','Fechando a porta…'],'Ordem ou pedido: <b>imperativo</b>.'],['"Cantando" é uma forma nominal chamada:','gerúndio',['infinitivo','particípio','imperativo'],'Terminação -ndo: <b>gerúndio</b>.'],['O verbo "pôr" pertence à:','2ª conjugação',['1ª conjugação','3ª conjugação','nenhuma conjugação'],'"Pôr" vem do antigo "poer": pertence à <b>2ª conjugação</b>.']]}),
SKL('pronome','Pronomes','👉','Pronome substitui ou acompanha o nome. Este/esta = perto de quem fala; esse/essa = perto de quem ouve; aquele = longe dos dois.',
`<ul><li><b>Pessoais retos</b> (sujeito): eu, tu, ele, nós, vós, eles. <b>Oblíquos</b> (complemento): me, te, o, a, lhe, nos, vos, os, as, lhes; mim, ti, si, comigo…</li><li><b>Possessivos</b>: meu, teu, seu, nosso…</li><li><b>Demonstrativos</b>: este (perto de quem fala / o que vai ser dito), esse (perto de quem ouve / o que já foi dito), aquele (distante).</li><li><b>Relativos</b>: que, quem, o qual, cujo, onde — retomam um termo anterior. <i>Cujo</i> indica posse e não admite artigo depois: <i>o autor <b>cujo livro</b> li</i>.</li><li><b>Indefinidos</b>: alguém, ninguém, tudo, algum…; <b>interrogativos</b>: que, quem, qual, quanto.</li><li><b>Tratamento</b>: você, Vossa Excelência, Vossa Senhoria… (verbo na 3ª pessoa).</li></ul>
<h3>Uso culto</h3><p><i>Isto é <b>para eu</b> fazer</i> (eu é sujeito de "fazer"); <i>Isto é <b>para mim</b></i> (complemento). <i>Entre <b>mim</b> e você</i>. O pronome <b>o/a</b> é objeto direto (<i>Eu o vi</i>); <b>lhe</b> é objeto indireto (<i>Eu lhe disse</i>).</p>
<h3>Colocação pronominal</h3><p>Palavras atrativas (não, nunca, que, quem, advérbios, pronomes indefinidos) puxam o pronome para antes do verbo (<b>próclise</b>): <i>Não <b>me</b> diga.</i> Não se inicia frase com pronome oblíquo na norma culta: <i>Diga-<b>me</b></i> (ênclise).</p>`,
{qs:[['Qual frase está de acordo com a norma culta?','Este livro é para eu ler.',['Este livro é para mim ler.','Entre eu e você não há segredo.','Me empreste o lápis, por favor.'],'Antes de verbo no infinitivo, com função de sujeito, usa-se <b>eu</b>: "para eu ler".'],['Em "O escritor cujo livro li", o pronome "cujo" indica:','posse',['lugar','tempo','causa'],'<b>Cujo</b> é relativo com ideia de posse (o livro do escritor).'],['Qual frase segue a norma culta de colocação pronominal?','Não me disseram nada.',['Não disseram-me nada.','Me disseram nada.','Nada disseram-me.'],'"Não" é palavra atrativa: exige próclise.'],['"___ caneta que está aqui na minha mão é azul." Complete:','Esta',['Essa','Aquela','Esse'],'Perto de quem fala: <b>este/esta</b>.'],['Na frase "Eu o encontrei na rua", o pronome "o" exerce a função de:','objeto direto',['objeto indireto','sujeito','adjunto adverbial'],'Os pronomes o, a, os, as funcionam como <b>objeto direto</b>.'],['"Onde" deve ser usado para retomar:','lugar físico',['tempo','situação qualquer','pessoa'],'Na norma culta, <b>onde</b> refere-se a lugar: "A cidade onde nasci".']],
 pairs:[['Pronome pessoal reto','exerce a função de sujeito: eu, tu, ele, nós, vós, eles'],['Pronome oblíquo','exerce a função de complemento: me, te, o, lhe, mim, ti'],['Pronome possessivo','indica posse: meu, teu, seu, nosso'],['Pronome demonstrativo','situa no espaço, no tempo ou no texto: este, esse, aquele'],['Pronome relativo','retoma um termo anterior: que, quem, o qual, cujo, onde'],['Pronome indefinido','refere-se de modo vago: alguém, ninguém, tudo, algum']]}),
SKL('conect','Advérbio, preposição e conjunção','🔗','Conjunções têm valor de sentido: mas (oposição), pois (explicação), portanto (conclusão), embora (concessão), se (condição).',
`<p><b>Advérbio</b> modifica verbo, adjetivo ou outro advérbio, indicando circunstância: tempo (<i>ontem</i>), lugar (<i>aqui</i>), modo (<i>bem, rapidamente</i>), intensidade (<i>muito</i>), negação (<i>não</i>), dúvida (<i>talvez</i>).</p>
<p><b>Preposição</b> liga termos: a, ante, após, até, com, contra, de, desde, em, entre, para, perante, por, sem, sob, sobre, trás.</p>
<h3>Conjunções coordenativas</h3><ul><li><b>Aditivas</b>: e, nem, não só… mas também.</li><li><b>Adversativas</b>: mas, porém, contudo, todavia, entretanto, no entanto.</li><li><b>Alternativas</b>: ou… ou, ora… ora.</li><li><b>Conclusivas</b>: logo, portanto, por isso, pois (depois do verbo).</li><li><b>Explicativas</b>: porque, que, pois (antes do verbo).</li></ul>
<h3>Conjunções subordinativas</h3><p><b>Causais</b> (porque, como, já que), <b>concessivas</b> (embora, ainda que, mesmo que), <b>condicionais</b> (se, caso, desde que), <b>temporais</b> (quando, assim que), <b>finais</b> (para que, a fim de que), <b>consecutivas</b> (tão… que), <b>comparativas</b> (como, tal qual), <b>conformativas</b> (conforme, segundo), <b>proporcionais</b> (à medida que, à proporção que).</p>`,
{pairs:[['mas / porém / contudo','valor adversativo (oposição)'],['portanto / logo','valor conclusivo'],['embora / ainda que','valor concessivo'],['se / caso','valor condicional'],['quando / assim que','valor temporal'],['para que / a fim de que','valor final (finalidade)'],['conforme / segundo','valor conformativo'],['à medida que','valor proporcional'],['já que / visto que','valor causal'],['tão… que','valor consecutivo']],tq:t=>`A conjunção <b>${t}</b> tem:`,dq:d=>`Qual conjunção tem <b>${d}</b>?`,
 qs:[['Em "Estudou muito, <b>portanto</b> foi aprovado", a conjunção expressa:','conclusão',['oposição','concessão','condição'],'"Portanto" introduz uma <b>conclusão</b>.'],['"<b>Embora</b> chovesse, fomos à praia." A conjunção indica:','concessão',['causa','condição','finalidade'],'Um fato contrário que não impede o outro: <b>concessão</b>.'],['Em "Ele chegou <b>ontem</b>", a palavra destacada é advérbio de:','tempo',['lugar','modo','intensidade'],'"Ontem" indica <b>tempo</b>.'],['Qual conjunção pode substituir "mas" sem mudar o sentido em "Tentei, mas não consegui"?','porém',['portanto','porque','conforme'],'<b>Porém</b> também é adversativa.'],['Em "Venha logo, <b>pois</b> vai chover", "pois" é:','explicativa',['conclusiva','adversativa','concessiva'],'"Pois" antes do verbo e após pedido/ordem: <b>explicativa</b>.'],['Em "Ele fala <b>muito</b> bem", o advérbio "muito" modifica:','outro advérbio',['um verbo','um substantivo','um adjetivo'],'"Muito" intensifica o advérbio "bem".']]})
]});

/* ------------------------ UNIDADE 3 — SINTAXE ------------------------ */
UNITS.push({id:'p3',title:'Sintaxe',sub:'Sujeito, complementos, concordância, regência, crase e orações',color:'#ff9600',dark:'#e07b00',skills:[
SKL('sujeito','Sujeito e predicado','🎯','Pergunte ao verbo "quem?" ou "o quê?". Verbos de fenômeno da natureza e "haver" (= existir) formam orações sem sujeito.',
`<p><b>Sujeito</b> é o termo sobre o qual se declara algo; <b>predicado</b> é o que se declara sobre ele. O verbo concorda com o sujeito.</p>
<ul><li><b>Simples</b>: um núcleo (<i><b>Os alunos</b> saíram.</i>)</li><li><b>Composto</b>: dois ou mais núcleos (<i><b>Ana e Rui</b> saíram.</i>)</li><li><b>Oculto (desinencial)</b>: identificado pela terminação do verbo (<i>Saímos cedo.</i> → nós)</li><li><b>Indeterminado</b>: verbo na 3ª pessoa do plural sem referente (<i><b>Roubaram</b> meu carro.</i>) ou 3ª do singular + <b>se</b> com verbo que não é transitivo direto (<i><b>Precisa-se</b> de ajudantes.</i>)</li><li><b>Oração sem sujeito</b>: fenômenos da natureza (<i>Choveu.</i>), <b>haver</b> no sentido de existir ou tempo (<i>Há vagas.</i>), <b>fazer</b> indicando tempo (<i>Faz dez anos.</i>).</li></ul>
<div class="ex">"Vendem-se casas." → sujeito <b>casas</b> (voz passiva sintética: casas são vendidas), por isso o verbo vai ao plural.</div>`,
{qs:[['Em "Choveu muito ontem", o sujeito é:','inexistente (oração sem sujeito)',['oculto','indeterminado','"ontem"'],'Verbos que indicam fenômenos da natureza formam <b>oração sem sujeito</b>.'],['Em "Roubaram minha bicicleta", o sujeito é:','indeterminado',['oculto (eles)','"minha bicicleta"','inexistente'],'Verbo na 3ª pessoa do plural sem referente no texto: <b>indeterminado</b>.'],['Em "Chegamos cedo à escola", o sujeito é:','oculto (nós)',['indeterminado','"escola"','inexistente'],'A desinência -mos indica "nós": sujeito <b>oculto</b> (desinencial).'],['Em "Precisa-se de professores", o sujeito é:','indeterminado',['"professores"','oculto','simples'],'"Precisar" é transitivo indireto: com "se" indetermina o sujeito, e o verbo fica no singular.'],['Em "Vendem-se apartamentos", o sujeito é:','"apartamentos"',['indeterminado','oculto','inexistente'],'Voz passiva sintética: apartamentos são vendidos → sujeito <b>apartamentos</b>.'],['Em "Há muitos alunos na sala", o verbo "haver":','forma oração sem sujeito e fica no singular',['concorda com "alunos"','tem sujeito oculto','tem sujeito indeterminado'],'"Haver" no sentido de existir é impessoal: <b>Há</b> muitos alunos (nunca "hão").'],['Em "O pai e a mãe chegaram", o sujeito é:','composto',['simples','oculto','indeterminado'],'Dois núcleos (pai, mãe): <b>composto</b>.']],
 pairs:[['Sujeito simples','tem um único núcleo'],['Sujeito composto','tem dois ou mais núcleos'],['Sujeito oculto','não aparece, mas é identificado pela desinência do verbo'],['Sujeito indeterminado','existe, mas não se pode ou não se quer identificá-lo'],['Oração sem sujeito','formada por verbos impessoais, como fenômenos da natureza e "haver" (existir)']]}),
SKL('complem','Verbos e complementos','🧩','VTD pede complemento sem preposição (objeto direto); VTI pede com preposição (objeto indireto); verbo de ligação liga o sujeito a um predicativo.',
`<ul><li><b>Intransitivo</b>: tem sentido completo (<i>O bebê dormiu.</i>).</li><li><b>Transitivo direto (VTD)</b>: complemento sem preposição — <b>objeto direto</b> (<i>Comprei <b>pão</b>.</i>).</li><li><b>Transitivo indireto (VTI)</b>: complemento com preposição obrigatória — <b>objeto indireto</b> (<i>Gosto <b>de música</b>.</i>).</li><li><b>Transitivo direto e indireto</b>: os dois (<i>Dei <b>o livro</b> <b>ao aluno</b>.</i>).</li><li><b>De ligação</b>: ser, estar, parecer, permanecer, ficar, continuar, andar (= estar) + <b>predicativo do sujeito</b> (<i>Ela <b>está</b> cansada.</i>).</li></ul>
<h3>Tipos de predicado</h3><p><b>Verbal</b> (núcleo é verbo de ação), <b>nominal</b> (verbo de ligação + predicativo) e <b>verbo-nominal</b> (ação + predicativo: <i>Os alunos saíram <b>felizes</b>.</i>).</p>
<p><b>Agente da passiva</b>: quem pratica a ação na voz passiva (<i>O livro foi escrito <b>por Machado</b>.</i>).</p>`,
{qs:[['Em "Ela entregou o relatório ao chefe", "o relatório" e "ao chefe" são, respectivamente:','objeto direto e objeto indireto',['objeto indireto e objeto direto','sujeito e predicativo','adjunto adnominal e adjunto adverbial'],'Entregar algo (OD) a alguém (OI): verbo transitivo direto e indireto.'],['Em "O menino parece cansado", "cansado" é:','predicativo do sujeito',['objeto direto','adjunto adnominal','agente da passiva'],'"Parecer" é verbo de ligação: "cansado" é <b>predicativo do sujeito</b>.'],['Em "Gosto de chocolate", o verbo é:','transitivo indireto',['transitivo direto','intransitivo','de ligação'],'Quem gosta, gosta <b>de</b> algo: exige preposição.'],['Em "A casa foi construída pelos operários", "pelos operários" é:','agente da passiva',['objeto indireto','sujeito','adjunto adnominal'],'Voz passiva analítica: quem pratica a ação é o <b>agente da passiva</b>.'],['Em "O avião caiu", o verbo é:','intransitivo',['transitivo direto','transitivo indireto','de ligação'],'Sentido completo, sem complemento: <b>intransitivo</b>.'],['Qual predicado é verbo-nominal?','Os jogadores voltaram cansados.',['Os jogadores estão cansados.','Os jogadores voltaram.','Os jogadores venceram o jogo.'],'Há ação (voltaram) e estado do sujeito (cansados): <b>verbo-nominal</b>.']],
 pairs:[['Verbo intransitivo','não precisa de complemento'],['Verbo transitivo direto','exige complemento sem preposição'],['Verbo transitivo indireto','exige complemento com preposição'],['Verbo de ligação','liga o sujeito a uma característica (predicativo)'],['Predicativo do sujeito','característica atribuída ao sujeito por meio do verbo'],['Agente da passiva','quem pratica a ação na voz passiva, introduzido por "por"']]}),
SKL('acess','Termos acessórios e vocativo','📌','Adjunto adnominal acompanha o nome; adjunto adverbial indica circunstância; aposto explica um termo; vocativo chama o interlocutor.',
`<ul><li><b>Adjunto adnominal</b>: acompanha e caracteriza o substantivo — artigos, adjetivos, pronomes, numerais, locuções (<i><b>Os dois</b> livros <b>antigos</b> <b>de meu avô</b></i>).</li><li><b>Adjunto adverbial</b>: indica circunstância de tempo, lugar, modo, causa… (<i>Saí <b>cedo</b> <b>de casa</b>.</i>).</li><li><b>Aposto</b>: explica ou resume um termo, geralmente entre vírgulas (<i>Machado, <b>o Bruxo do Cosme Velho</b>, …</i>).</li><li><b>Vocativo</b>: chama o interlocutor e não faz parte nem do sujeito nem do predicado (<i><b>Professor</b>, posso sair?</i>).</li></ul>
<div class="ex">Complemento nominal × adjunto adnominal: em "a crítica <b>do professor</b>", se o professor critica, é adjunto (agente); em "a crítica <b>ao professor</b>", ele é criticado: complemento nominal (paciente).</div>`,
{qs:[['Em "Amanhã, eu viajarei de ônibus", "amanhã" e "de ônibus" são:','adjuntos adverbiais de tempo e de meio',['adjuntos adnominais','objetos indiretos','apostos'],'Indicam circunstâncias (tempo e meio): <b>adjuntos adverbiais</b>.'],['Em "Senhores, a sessão está aberta", "Senhores" é:','vocativo',['sujeito','aposto','adjunto adnominal'],'Termo usado para chamar os ouvintes: <b>vocativo</b>.'],['Em "Recife, a capital pernambucana, é linda", o termo destacado entre vírgulas é:','aposto',['vocativo','predicativo','adjunto adverbial'],'Explica "Recife": <b>aposto</b>.'],['Em "O velho relógio da sala parou", "velho" e "da sala" são:','adjuntos adnominais',['adjuntos adverbiais','complementos nominais','predicativos'],'Caracterizam o substantivo "relógio": <b>adjuntos adnominais</b>.'],['Em "Tenho medo <b>de altura</b>", o termo destacado é:','complemento nominal',['adjunto adnominal','objeto indireto','agente da passiva'],'Completa o sentido do nome "medo" (medo de quê?): <b>complemento nominal</b>.']]}),
SKL('concord','Concordância','🤝','O verbo concorda com o sujeito; "haver" (existir) fica no singular; o adjetivo concorda com o substantivo.',
`<h3>Concordância verbal</h3><ul><li>O verbo concorda com o núcleo do sujeito: <i>A lista de nomes <b>foi</b> entregue.</i></li><li>Sujeito composto antes do verbo → plural: <i>Pai e filho <b>chegaram</b>.</i></li><li><b>Haver</b> = existir e <b>fazer</b> = tempo ficam no singular: <i><b>Havia</b> muitas pessoas. <b>Faz</b> dois anos.</i></li><li>Voz passiva sintética concorda: <i><b>Alugam-se</b> casas.</i></li><li>"Mais de um" pede singular: <i>Mais de um aluno <b>faltou</b>.</i></li><li>Porcentagem concorda com o numeral ou com o termo especificado: <i>30% dos alunos <b>faltaram</b>.</i></li></ul>
<h3>Concordância nominal</h3><ul><li>O adjetivo concorda com o substantivo: <i>blusas <b>caras</b></i>.</li><li><b>Meio</b> (advérbio = um pouco) é invariável: <i>Ela está <b>meio</b> cansada.</i> Como numeral varia: <i>meia hora</i>.</li><li><b>Bastante</b> concorda quando é adjetivo: <i><b>bastantes</b> livros</i> (= muitos).</li><li><b>Anexo, obrigado, mesmo, próprio, quite</b> concordam: <i>Seguem <b>anexas</b> as fotos. — <b>Obrigada</b>, disse ela.</i></li><li><b>É proibido, é necessário</b>: invariáveis sem artigo (<i>É proibido entrada</i>), variáveis com artigo (<i>É proibida <b>a</b> entrada</i>).</li></ul>`,
{bank:[['@@ muitas pessoas na fila.','Havia',['Haviam','Houveram','Hão'],'"Haver" = existir é impessoal: <b>Havia</b>.'],['@@ dez anos que não o vejo.','Faz',['Fazem','Fizeram','Fazemos'],'"Fazer" indicando tempo é impessoal: <b>Faz</b>.'],['@@ apartamentos na praia.','Vendem-se',['Vende-se','Vendeu-se','Vende-os'],'Voz passiva sintética: apartamentos são vendidos → <b>Vendem-se</b>.'],['Ela ficou @@ nervosa com a prova.','meio',['meia','meios','meias'],'Advérbio (= um pouco): <b>meio</b>, invariável.'],['Seguem @@ as notas fiscais.','anexas',['anexo','anexa','anexos'],'"Anexo" concorda com o substantivo: notas → <b>anexas</b>.'],['"Muito @@", disse a menina.','obrigada',['obrigado','obrigados','obrigadas'],'Concorda com quem fala: a menina → <b>obrigada</b>.'],['Mais de um aluno @@ a aula.','perdeu',['perderam','perdemos','perdi'],'"Mais de um" pede verbo no singular.'],['É @@ a entrada de animais.','proibida',['proibido','proibidas','proibidos'],'Com artigo ("a entrada"), concorda: <b>proibida</b>.'],['Os meninos e a menina @@ juntos.','saíram',['saiu','sai','saía'],'Sujeito composto anteposto: plural.']]}),
SKL('crase','Regência e crase','🔀','Crase = preposição "a" + artigo "a". Troque a palavra feminina por uma masculina: se virar "ao", há crase.',
`<h3>Regência</h3><p>É a relação entre um termo e seu complemento. Exemplos da norma culta:</p><ul><li><b>Assistir</b> (ver) é VTI: <i>assisti <b>ao</b> filme</i>. (Assistir = ajudar é VTD.)</li><li><b>Visar</b> (ter como objetivo) é VTI: <i>visa <b>ao</b> lucro</i>.</li><li><b>Obedecer / desobedecer</b> a: <i>obedeça <b>às</b> regras</i>.</li><li><b>Preferir</b> algo <b>a</b> outra coisa (sem "do que" e sem "mais"): <i>prefiro cinema <b>a</b> teatro</i>.</li><li><b>Ir, chegar</b> a um lugar (não "em"): <i>chegou <b>à</b> escola</i>.</li><li><b>Namorar</b> é VTD: <i>namora Pedro</i> (não "com").</li></ul>
<h3>Crase</h3><p>Fusão da preposição <b>a</b> com o artigo <b>a</b> (ou com "aquele", "aquela"). <b>Truque</b>: troque por uma palavra masculina — se aparecer <b>ao</b>, use <b>à</b>. <i>Vou <b>à</b> escola</i> (vou ao colégio).</p>
<ul><li><b>Não há crase</b> antes de palavra masculina, verbo, pronomes pessoais e de tratamento (<i>a ela, a Vossa Senhoria</i>), "a" no singular antes de plural (<i>a pessoas</i>) e entre palavras repetidas (<i>cara a cara</i>).</li><li><b>Há crase</b> em locuções adverbiais femininas (<i>às vezes, à noite, às pressas</i>) e na indicação de horas (<i>às 8h</i>).</li><li>Cidades: "vou a Recife, volto <b>de</b> Recife" → sem crase; "vou <b>à</b> Bahia, volto <b>da</b> Bahia" → com crase.</li></ul>`,
{bank:[['Vou @@ farmácia comprar remédio.','à',['a','há','ah'],'Vou ao mercado → vou <b>à</b> farmácia.'],['Começou @@ chover.','a',['à','há','ah'],'Antes de verbo não há crase.'],['A reunião será @@ 14h.','às',['as','a','há'],'Indicação de horas: <b>às</b> 14h.'],['Entreguei o livro @@ ela.','a',['à','há','às'],'Antes de pronome pessoal não há crase.'],['Assisti @@ filme ontem.','ao',['o','do','no'],'Assistir (ver) é VTI: assisti <b>ao</b> filme.'],['Prefiro sorvete @@ bolo.','a',['do que','que','à'],'Preferir algo <b>a</b> outra coisa.'],['Vou @@ Bahia nas férias.','à',['a','há','as'],'Volto da Bahia → vou <b>à</b> Bahia.'],['Vou @@ Curitiba amanhã.','a',['à','há','às'],'Volto de Curitiba → vou <b>a</b> Curitiba (sem crase).'],['Estudo @@ noite.','à',['a','há','na'],'Locução adverbial feminina: <b>à</b> noite.'],['Fiquei frente @@ frente com ele.','a',['à','há','às'],'Entre palavras repetidas não há crase.'],['Os alunos obedecem @@ regras.','às',['as','a','das'],'Obedecer <b>a</b> + as regras = <b>às</b> regras.'],['Ele chegou @@ escola atrasado.','à',['na','a','há'],'Chegar <b>a</b> um lugar: chegou à escola.']]}),
SKL('oracoes','Orações coordenadas e subordinadas','🧱','Coordenadas são independentes (ligadas por e, mas, ou, logo, pois); subordinadas dependem de uma oração principal.',
`<p><b>Período composto por coordenação</b>: orações sintaticamente independentes. <b>Assindéticas</b> (sem conjunção: <i>Cheguei, vi, venci.</i>) ou <b>sindéticas</b> (aditivas, adversativas, alternativas, conclusivas, explicativas).</p>
<p><b>Período composto por subordinação</b>: uma oração exerce função sintática na principal.</p><ul><li><b>Substantivas</b> (função de substantivo; geralmente introduzidas por <i>que</i> ou <i>se</i>): <i>Espero <b>que você venha</b></i> (objetiva direta).</li><li><b>Adjetivas</b> (introduzidas por pronome relativo): <b>restritivas</b> (sem vírgula) e <b>explicativas</b> (com vírgula).</li><li><b>Adverbiais</b>: causais, concessivas, condicionais, temporais, finais, consecutivas, comparativas, conformativas, proporcionais.</li></ul>
<div class="ex">"Saí cedo <b>porque tinha prova</b>" → adverbial causal. "O livro <b>que comprei</b> é ótimo" → adjetiva restritiva.</div>`,
{qs:[['"Estudei muito, mas não passei." A segunda oração é:','coordenada sindética adversativa',['subordinada adverbial concessiva','coordenada assindética','subordinada substantiva'],'"Mas" liga orações independentes com oposição.'],['"É importante que você estude." A oração destacada ("que você estude") é:','subordinada substantiva subjetiva',['subordinada adjetiva','coordenada explicativa','subordinada adverbial final'],'Funciona como sujeito de "é importante": <b>substantiva subjetiva</b>.'],['"O aluno que estudou foi aprovado." A oração "que estudou" é:','subordinada adjetiva restritiva',['subordinada adjetiva explicativa','coordenada aditiva','subordinada substantiva'],'Introduzida por pronome relativo, sem vírgulas: <b>adjetiva restritiva</b>.'],['"Se chover, o jogo será adiado." A oração "Se chover" é adverbial:','condicional',['causal','concessiva','temporal'],'"Se" expressa <b>condição</b>.'],['"Vim, vi, venci." As orações são:','coordenadas assindéticas',['coordenadas sindéticas aditivas','subordinadas adverbiais','subordinadas adjetivas'],'Sem conjunção: <b>assindéticas</b>.'],['"Falou tão alto que ficou rouco." A oração "que ficou rouco" é adverbial:','consecutiva',['causal','final','comparativa'],'"Tão… que": <b>consecutiva</b> (consequência).'],['"Estudo para que eu seja aprovado." A oração destacada é adverbial:','final',['causal','condicional','conformativa'],'"Para que" indica <b>finalidade</b>.']]})
]});

