UNITS.push({id:'p4',title:'Sentido e texto',sub:'Figuras de linguagem, funções da linguagem, gêneros, variação e coesão',color:'#ff4b4b',dark:'#ea2b2b',skills:[
SKL('figuras','Figuras de linguagem','🎭','Metáfora compara sem "como"; comparação usa "como"; metonímia troca um termo por outro com relação de proximidade (autor pela obra, parte pelo todo).',
`<h3>Figuras de palavra</h3><ul><li><b>Metáfora</b>: comparação implícita (<i>Meu coração é um balde despejado</i>).</li><li><b>Comparação (símile)</b>: com conectivo (<i>forte <b>como</b> um touro</i>).</li><li><b>Metonímia</b>: troca por proximidade — autor pela obra (<i>li Machado</i>), parte pelo todo (<i>não há teto para ele</i>), marca pelo produto (<i>tomei um Nescau</i>).</li><li><b>Catacrese</b>: metáfora já desgastada, por falta de termo próprio (<i>pé da mesa</i>).</li><li><b>Sinestesia</b>: mistura de sentidos (<i>voz <b>doce</b></i>, <i>cor <b>gritante</b></i>).</li></ul>
<h3>Figuras de pensamento</h3><ul><li><b>Hipérbole</b>: exagero (<i>chorei rios de lágrimas</i>).</li><li><b>Eufemismo</b>: suaviza (<i>ele partiu desta para melhor</i>).</li><li><b>Ironia</b>: diz o contrário do que pensa (<i>Que belo resultado: tirou zero!</i>).</li><li><b>Antítese</b>: ideias opostas (<i>alegria e tristeza</i>). <b>Paradoxo</b>: ideias opostas que parecem absurdas juntas (<i>"é dor que desatina sem doer"</i>).</li><li><b>Prosopopeia (personificação)</b>: ações humanas a seres inanimados (<i>o vento sussurrava</i>).</li><li><b>Gradação</b>: sequência crescente ou decrescente.</li></ul>
<h3>Figuras de som e de sintaxe</h3><p><b>Aliteração</b> (repetição de consoantes: <i>"o rato roeu a roupa do rei de Roma"</i>), <b>assonância</b> (repetição de vogais), <b>onomatopeia</b> (imita sons: <i>tic-tac</i>), <b>elipse</b> (omissão de termo fácil de subentender), <b>pleonasmo</b> (repetição enfática), <b>anáfora</b> (repetição no início de versos ou frases).</p>`,
{pairs:[['"Meu coração é um balde despejado."','metáfora'],['"Ele é forte como um touro."','comparação'],['"Li Machado de Assis nas férias."','metonímia'],['"Já te disse isso um milhão de vezes."','hipérbole'],['"Ele passou desta para melhor."','eufemismo'],['"Que bonito, hein? Tirou zero de novo!"','ironia'],['"O vento sussurrava segredos à janela."','prosopopeia'],['"Amor é fogo que arde sem se ver."','paradoxo'],['"Ouvi uma voz macia e doce."','sinestesia'],['"O pé da mesa quebrou."','catacrese'],['"O rato roeu a roupa do rei de Roma."','aliteração'],['"O tique-taque do relógio me acordou."','onomatopeia']],tq:t=>`Qual figura de linguagem aparece em <b>${t}</b>?`,dq:d=>`Qual frase exemplifica <b>${d}</b>?`,noTF:true,
 tf:[['A metáfora é uma comparação sem conectivo comparativo.',true,'Verdadeiro.'],['Na metonímia, há exagero intencional.',false,'Falso: exagero é hipérbole; metonímia é substituição por proximidade.'],['"Pé da mesa" é catacrese.',true,'Verdadeiro: metáfora cristalizada por falta de termo próprio.'],['Antítese e paradoxo são a mesma figura.',false,'Falso: na antítese as ideias opostas convivem; no paradoxo elas se fundem num sentido aparentemente absurdo.']]}),
SKL('funcoes','Funções da linguagem','📡','Emotiva (emissor), apelativa (receptor), referencial (contexto), metalinguística (código), poética (mensagem), fática (canal).',
`<p>Roman Jakobson relacionou cada elemento da comunicação a uma função:</p>
<table><tr><th>Elemento</th><th>Função</th><th>Exemplo</th></tr><tr><td>Emissor</td><td><b>Emotiva (expressiva)</b></td><td>diários, cartas pessoais, 1ª pessoa</td></tr><tr><td>Receptor</td><td><b>Apelativa (conativa)</b></td><td>propagandas, imperativo, vocativo</td></tr><tr><td>Referente/contexto</td><td><b>Referencial (denotativa)</b></td><td>notícias, textos científicos</td></tr><tr><td>Código</td><td><b>Metalinguística</b></td><td>dicionários, poema sobre fazer poemas</td></tr><tr><td>Mensagem</td><td><b>Poética</b></td><td>poemas, slogans com rimas e ritmo</td></tr><tr><td>Canal</td><td><b>Fática</b></td><td>"Alô?", "Tá me ouvindo?", "Né?"</td></tr></table>
<p>Um texto costuma ter várias funções, mas uma é <b>predominante</b>.</p>`,
{pairs:[['Função emotiva','centrada no emissor, expressa sentimentos e opiniões em 1ª pessoa'],['Função apelativa','centrada no receptor, tenta convencê-lo ou levá-lo a agir'],['Função referencial','centrada no contexto, informa de modo objetivo'],['Função metalinguística','usa o código para falar do próprio código'],['Função poética','centrada na elaboração da mensagem: ritmo, sonoridade, imagens'],['Função fática','centrada no canal: testa ou mantém o contato']],
 qs:[['Um verbete de dicionário apresenta predominantemente a função:','metalinguística',['emotiva','fática','apelativa'],'Explica palavras usando palavras: <b>metalinguística</b>.'],['Uma propaganda com "Compre já! Você merece!" tem predominância da função:','apelativa',['referencial','poética','fática'],'Centrada no receptor, com imperativo: <b>apelativa</b>.'],['Uma notícia de jornal sobre a alta dos preços tem predominância da função:','referencial',['emotiva','metalinguística','fática'],'Informação objetiva: <b>referencial</b>.'],['"Alô? Está me ouvindo?" exemplifica a função:','fática',['poética','apelativa','emotiva'],'Testa o canal de comunicação: <b>fática</b>.'],['Um poema que discute como se escreve um poema tem forte presença da função:','metalinguística',['referencial','fática','apelativa'],'O poema fala do próprio código (a poesia): <b>metalinguística</b>.']]}),
SKL('generos','Tipos e gêneros textuais','📰','Tipos são poucos (narrar, descrever, dissertar, expor, injuntar); gêneros são muitos (notícia, crônica, receita, editorial…).',
`<p><b>Tipos textuais</b> são modos de organização: <b>narrativo</b> (fatos no tempo, personagens), <b>descritivo</b> (características), <b>dissertativo-argumentativo</b> (defende tese com argumentos), <b>expositivo</b> (explica), <b>injuntivo</b> (instrui, com imperativo).</p>
<p><b>Gêneros textuais</b> são textos concretos do dia a dia, definidos por função social, estrutura e suporte:</p><ul><li><b>Notícia</b>: relata fato recente, linguagem objetiva, lide (o quê, quem, quando, onde, como, por quê).</li><li><b>Reportagem</b>: aprofunda um tema com dados e entrevistas.</li><li><b>Editorial</b>: opinião do veículo, sem assinatura.</li><li><b>Artigo de opinião</b>: opinião assinada.</li><li><b>Crônica</b>: fato do cotidiano com olhar pessoal, muitas vezes humor ou lirismo.</li><li><b>Conto</b>: narrativa curta com poucos personagens e um conflito.</li><li><b>Receita, manual</b>: injuntivos. <b>Charge</b>: humor crítico sobre fato atual.</li></ul>
<h3>Redação do ENEM</h3><p>Texto <b>dissertativo-argumentativo</b> com tese, argumentos e <b>proposta de intervenção</b> detalhada (agente, ação, meio, finalidade, detalhamento), respeitando os direitos humanos.</p>`,
{pairs:[['Notícia','relata um fato recente de forma objetiva'],['Editorial','expressa a opinião do próprio jornal, sem assinatura'],['Crônica','comenta o cotidiano com olhar pessoal, muitas vezes com humor'],['Receita culinária','gênero injuntivo, com instruções no imperativo'],['Charge','critica com humor um fato atual, por meio de desenho'],['Artigo de opinião','defende o ponto de vista de um autor que o assina'],['Conto','narrativa curta com poucos personagens e um conflito central'],['Reportagem','aprofunda um tema com dados, pesquisa e entrevistas']],tq:t=>`O gênero <b>${t}</b>:`,dq:d=>`Qual gênero textual <b>${d}</b>?`,
 qs:[['A redação do ENEM exige um texto do tipo:','dissertativo-argumentativo',['narrativo','descritivo','injuntivo'],'Tese + argumentos + proposta de intervenção.'],['Um manual de instruções é predominantemente:','injuntivo',['narrativo','descritivo','argumentativo'],'Instrui o leitor, com verbos no imperativo: <b>injuntivo</b>.'],['Qual elemento é obrigatório na proposta de intervenção da redação do ENEM, segundo a matriz de correção?','agente, ação, meio, finalidade e detalhamento',['citação de autor famoso','título','rima'],'A proposta de intervenção completa tem <b>agente, ação, meio/modo, finalidade e detalhamento</b>, respeitando os direitos humanos.']]}),
SKL('variacao','Variação linguística','🗣️','Não existe "erro" na fala espontânea, e sim adequação: cada situação pede uma variedade. A norma-padrão é a exigida em contextos formais.',
`<p>A língua varia conforme:</p><ul><li><b>Região (diatópica)</b>: "mandioca, aipim, macaxeira"; sotaques.</li><li><b>Grupo social (diastrática)</b>: idade, escolaridade, profissão (jargões), gírias.</li><li><b>Situação (diafásica)</b>: formal × informal.</li><li><b>Tempo (diacrônica)</b>: "Vossa Mercê → vosmecê → você".</li><li><b>Modalidade (diamésica)</b>: fala × escrita.</li></ul>
<p><b>Preconceito linguístico</b> é discriminar alguém pela forma como fala. O conceito-chave é a <b>adequação</b>: a norma-padrão é adequada a situações formais, e as variedades informais, às cotidianas.</p>`,
{pairs:[['Variação regional (diatópica)','diferenças de acordo com o lugar, como "mandioca", "aipim" e "macaxeira"'],['Variação social (diastrática)','diferenças ligadas a grupo social, idade ou profissão'],['Variação situacional (diafásica)','ajuste ao grau de formalidade da situação'],['Variação histórica (diacrônica)','mudanças da língua ao longo do tempo'],['Jargão','vocabulário próprio de uma profissão ou área'],['Preconceito linguístico','discriminação de pessoas pelo modo como falam']],
 qs:[['"Vossa mercê" se transformou em "você" ao longo dos séculos. Isso é um exemplo de variação:','histórica',['regional','social','situacional'],'Mudança ao longo do tempo: <b>diacrônica</b>.'],['Segundo a Linguística, a forma mais adequada de avaliar a fala de alguém é pelo critério de:','adequação à situação comunicativa',['certo e errado absolutos','quantidade de palavras difíceis','sotaque da capital'],'Não há variedade superior; há <b>adequação</b> ao contexto.'],['O vocabulário técnico de médicos ("anamnese", "profilaxia") é chamado de:','jargão',['gíria regional','arcaísmo','neologismo'],'<b>Jargão</b>: linguagem própria de um grupo profissional.']]}),
SKL('coesao','Coesão e coerência','🧵','Coesão é a ligação entre as partes do texto (pronomes, sinônimos, conectivos); coerência é o sentido lógico do todo.',
`<p><b>Coesão</b>: mecanismos que ligam palavras, frases e parágrafos.</p><ul><li><b>Referencial</b>: retomar termos com pronomes, sinônimos, hiperônimos, elipse (<i>Maria chegou. <b>Ela</b> estava cansada.</i>). <b>Anáfora</b> retoma o que já foi dito; <b>catáfora</b> antecipa o que vai ser dito.</li><li><b>Sequencial</b>: conectivos que expressam relações lógicas (<i>além disso, no entanto, portanto, porque</i>).</li></ul>
<p><b>Coerência</b>: o texto faz sentido, sem contradições, com informações compatíveis com o mundo e com o próprio texto.</p>
<div class="ex">"Choveu muito, <b>portanto</b> a rua ficou seca." → conectivo coeso, mas o texto é <b>incoerente</b>.</div>`,
{qs:[['Em "João comprou um carro. <b>O veículo</b> é azul.", o termo destacado é um recurso de:','coesão referencial',['coesão sequencial','incoerência','ambiguidade'],'Retoma "carro" com um hiperônimo: <b>coesão referencial</b>.'],['Qual conectivo expressa ideia de <b>adição</b>?','além disso',['no entanto','portanto','embora'],'<b>Além disso</b> acrescenta informação.'],['"Estava com fome, portanto não comeu nada." O problema dessa frase é de:','coerência',['ortografia','concordância','acentuação'],'"Portanto" anuncia uma conclusão que contradiz a causa: falta <b>coerência</b>.'],['Em "Só quero isto: <b>paz</b>", o pronome "isto" antecipa o termo "paz". Esse recurso é a:','catáfora',['anáfora','elipse','hipérbole'],'Pronome que se refere ao que <b>vem depois</b>: catáfora.'],['Qual conectivo pode substituir "no entanto" sem alterar o sentido?','contudo',['portanto','porque','além disso'],'Ambos são <b>adversativos</b>.']],
 pairs:[['Anáfora (coesão)','retomada de um termo que já apareceu no texto'],['Catáfora','antecipação de um termo que ainda vai aparecer'],['Elipse','omissão de um termo que se subentende pelo contexto'],['Hiperônimo','palavra de sentido mais geral que retoma outra, como "veículo" para "carro"'],['Coerência','unidade de sentido e lógica do texto'],['Coesão sequencial','encadeamento de ideias por meio de conectivos']]})
]});

