UNITS.push({id:'p5',title:'Literatura brasileira',sub:'Do Quinhentismo ao Modernismo: escolas, autores e obras',color:'#2b70c9',dark:'#1f569e',skills:[
SKL('lit1','Quinhentismo, Barroco e Arcadismo','⛵','Quinhentismo: textos de informação e catequese; Barroco: conflito e rebuscamento; Arcadismo: simplicidade, bucolismo e razão.',
`<ul><li><b>Quinhentismo (séc. XVI)</b>: literatura de informação (<i>Carta</i> de Pero Vaz de Caminha, 1500) e de catequese (padre <b>José de Anchieta</b>).</li><li><b>Barroco (séc. XVII)</b>: tensão entre fé e prazer, efemeridade da vida, antíteses e paradoxos; <b>cultismo</b> (jogo de palavras) e <b>conceptismo</b> (jogo de ideias). <b>Gregório de Matos</b>, o "Boca do Inferno" (poesia satírica, lírica e religiosa); <b>Padre Antônio Vieira</b> (<i>Sermões</i>, como o <i>Sermão da Sexagésima</i>).</li><li><b>Arcadismo (séc. XVIII)</b>: reação ao Barroco; simplicidade, vida no campo (<i>fugere urbem</i>, <i>locus amoenus</i>), pastores, <i>carpe diem</i>; ligação com a Inconfidência Mineira. <b>Tomás Antônio Gonzaga</b> (<i>Marília de Dirceu</i>, <i>Cartas Chilenas</i>), <b>Cláudio Manuel da Costa</b>, <b>Basílio da Gama</b> (<i>O Uraguai</i>), <b>Santa Rita Durão</b> (<i>Caramuru</i>).</li></ul>`,
{pairs:[['Pero Vaz de Caminha','autor da Carta que relata a chegada dos portugueses ao Brasil (Quinhentismo)'],['José de Anchieta','jesuíta da literatura de catequese (Quinhentismo)'],['Gregório de Matos','poeta barroco satírico, apelidado de "Boca do Inferno"'],['Padre Antônio Vieira','autor barroco dos Sermões, como o Sermão da Sexagésima'],['Tomás Antônio Gonzaga','poeta árcade autor de Marília de Dirceu'],['Basílio da Gama','autor árcade do poema épico O Uraguai'],['Santa Rita Durão','autor árcade do poema épico Caramuru']],
 qs:[['Uma característica do Barroco é:','o uso de antíteses e paradoxos, expressando conflito entre fé e prazer',['a exaltação do indígena como herói nacional','a busca da "arte pela arte"','o verso livre e a linguagem coloquial'],'O Barroco expressa o conflito espiritual com antíteses e paradoxos.'],['"Fugere urbem" (fugir da cidade) e "locus amoenus" (lugar ameno) são ideais do:','Arcadismo',['Barroco','Romantismo','Modernismo'],'Ideais <b>árcades</b> de vida simples no campo.'],['O Arcadismo mineiro está ligado a qual movimento histórico?','Inconfidência Mineira',['Revolução Farroupilha','Proclamação da República','Semana de Arte Moderna'],'Poetas como Gonzaga e Cláudio Manuel da Costa participaram da <b>Inconfidência Mineira</b>.']]}),
SKL('lit2','Romantismo','🌹','Três gerações de poesia: indianista/nacionalista (Gonçalves Dias), ultrarromântica (Álvares de Azevedo) e condoreira (Castro Alves).',
`<p>Início no Brasil: <i>Suspiros Poéticos e Saudades</i> (1836), de Gonçalves de Magalhães. Valoriza o <b>sentimento</b>, o <b>nacionalismo</b>, o <b>subjetivismo</b>, a idealização da mulher e da natureza.</p>
<ul><li><b>1ª geração (indianista/nacionalista)</b>: <b>Gonçalves Dias</b> — "Canção do Exílio" ("Minha terra tem palmeiras…"), "I-Juca-Pirama".</li><li><b>2ª geração (ultrarromântica, "mal do século")</b>: pessimismo, morte, amor impossível — <b>Álvares de Azevedo</b> (<i>Lira dos Vinte Anos</i>, <i>Noite na Taverna</i>), <b>Casimiro de Abreu</b> ("Meus oito anos"), <b>Fagundes Varela</b>.</li><li><b>3ª geração (condoreira/social)</b>: abolicionismo e crítica social — <b>Castro Alves</b>, o "poeta dos escravos" (<i>O Navio Negreiro</i>).</li></ul>
<h3>Prosa</h3><p><b>José de Alencar</b>: indianistas (<i>Iracema</i>, <i>O Guarani</i>, <i>Ubirajara</i>), urbanos (<i>Senhora</i>, <i>Lucíola</i>) e regionalistas (<i>O Sertanejo</i>). <b>Joaquim Manuel de Macedo</b> (<i>A Moreninha</i>, 1844), <b>Manuel Antônio de Almeida</b> (<i>Memórias de um Sargento de Milícias</i>), <b>Bernardo Guimarães</b> (<i>A Escrava Isaura</i>), <b>Visconde de Taunay</b> (<i>Inocência</i>).</p>`,
{pairs:[['Gonçalves Dias','poeta da 1ª geração romântica, autor da "Canção do Exílio"'],['Álvares de Azevedo','poeta ultrarromântico, autor de Lira dos Vinte Anos'],['Castro Alves','poeta condoreiro, autor de O Navio Negreiro'],['José de Alencar','romancista de Iracema, O Guarani e Senhora'],['Joaquim Manuel de Macedo','autor de A Moreninha (1844)'],['Bernardo Guimarães','autor de A Escrava Isaura'],['Manuel Antônio de Almeida','autor de Memórias de um Sargento de Milícias']],
 qs:[['A 2ª geração romântica, marcada pelo pessimismo, pela morte e pelo "mal do século", tem como principal nome:','Álvares de Azevedo',['Castro Alves','Gonçalves Dias','Olavo Bilac'],'<b>Álvares de Azevedo</b> é o maior nome do ultrarromantismo.'],['"Minha terra tem palmeiras / Onde canta o Sabiá" é de:','Gonçalves Dias',['Castro Alves','Casimiro de Abreu','Carlos Drummond de Andrade'],'"Canção do Exílio" (1843), de <b>Gonçalves Dias</b>.'],['A poesia condoreira de Castro Alves caracteriza-se:','pela crítica social e pelo abolicionismo',['pelo indianismo idealizado','pela obsessão com a morte','pela arte pela arte'],'Poesia social, com o "voo do condor": abolicionismo.'],['Iracema, "a virgem dos lábios de mel", é personagem de um romance:','indianista de José de Alencar',['urbano de Machado de Assis','naturalista de Aluísio Azevedo','modernista de Mário de Andrade'],'<i>Iracema</i> (1865), romance <b>indianista</b> de Alencar.']]}),
SKL('lit3','Realismo, Naturalismo, Parnasianismo e Simbolismo','🔍','Realismo: análise psicológica e crítica (Machado); Naturalismo: determinismo (Aluísio Azevedo); Parnasianismo: arte pela arte (Bilac); Simbolismo: musicalidade e mistério (Cruz e Sousa).',
`<ul><li><b>Realismo (1881)</b>: objetividade, crítica à burguesia, análise psicológica, ironia. Marco: <i>Memórias Póstumas de Brás Cubas</i> (1881), de <b>Machado de Assis</b>, que também escreveu <i>Dom Casmurro</i> (a dúvida sobre Capitu) e <i>Quincas Borba</i>.</li><li><b>Naturalismo</b>: o ser humano determinado por meio, raça e momento histórico (<b>determinismo</b>), linguagem crua, zoomorfização. <b>Aluísio Azevedo</b> (<i>O Mulato</i>, 1881; <i>O Cortiço</i>, 1890), <b>Adolfo Caminha</b> (<i>Bom-Crioulo</i>).</li><li><b>Parnasianismo</b>: "arte pela arte", rigor formal, soneto, rimas ricas, temas clássicos. Tríade: <b>Olavo Bilac</b>, <b>Alberto de Oliveira</b> e <b>Raimundo Correia</b>.</li><li><b>Simbolismo (1893)</b>: musicalidade, sinestesia, espiritualidade, mistério, cor branca. <b>Cruz e Sousa</b> (<i>Broquéis</i> e <i>Missal</i>, 1893) e <b>Alphonsus de Guimaraens</b> ("Ismália").</li></ul>`,
{pairs:[['Machado de Assis','autor realista de Memórias Póstumas de Brás Cubas e Dom Casmurro'],['Aluísio Azevedo','autor naturalista de O Cortiço'],['Olavo Bilac','principal poeta parnasiano, defensor do rigor formal'],['Cruz e Sousa','principal poeta simbolista, autor de Broquéis'],['Alphonsus de Guimaraens','poeta simbolista autor de "Ismália"'],['Raul Pompeia','autor de O Ateneu, romance sobre um colégio interno']],
 qs:[['O determinismo (o ser humano moldado pelo meio, pela raça e pelo momento) é característica do:','Naturalismo',['Romantismo','Simbolismo','Arcadismo'],'O <b>Naturalismo</b> aplica ideias científicas do séc. XIX à literatura.'],['O lema "arte pela arte" e o gosto pelo soneto perfeito caracterizam o:','Parnasianismo',['Simbolismo','Romantismo','Modernismo'],'Rigor formal e culto da forma: <b>Parnasianismo</b>.'],['A dúvida sobre a traição de Capitu é o centro de:','Dom Casmurro',['O Cortiço','Iracema','Senhora'],'<i>Dom Casmurro</i> (1899), narrado por Bentinho.'],['Musicalidade, sinestesia e espiritualidade são marcas do:','Simbolismo',['Naturalismo','Parnasianismo','Realismo'],'<b>Simbolismo</b>, com Cruz e Sousa.'],['O marco inicial do Realismo no Brasil é:','Memórias Póstumas de Brás Cubas (1881)',['O Guarani (1857)','Os Sertões (1902)','Macunaíma (1928)'],'Machado de Assis, 1881.']]}),
SKL('lit4','Pré-Modernismo e Modernismo','🎨','A Semana de Arte Moderna (1922) rompe com o passado: verso livre, linguagem coloquial, humor e nacionalismo crítico.',
`<p><b>Pré-Modernismo</b> (1902–1922): denúncia da realidade brasileira. <b>Euclides da Cunha</b> (<i>Os Sertões</i>, 1902, sobre Canudos), <b>Lima Barreto</b> (<i>Triste Fim de Policarpo Quaresma</i>), <b>Monteiro Lobato</b> (<i>Urupês</i>, o Jeca Tatu), <b>Augusto dos Anjos</b> (<i>Eu</i>).</p>
<h3>Modernismo</h3><ul><li><b>1ª fase (1922–1930, "heroica")</b>: Semana de Arte Moderna (fevereiro de 1922, Theatro Municipal de São Paulo); ruptura, verso livre, humor, poema-piada. <b>Mário de Andrade</b> (<i>Macunaíma</i>, <i>Pauliceia Desvairada</i>), <b>Oswald de Andrade</b> (<i>Manifesto Antropófago</i>, 1928), <b>Manuel Bandeira</b> ("Os Sapos", "Vou-me embora pra Pasárgada").</li><li><b>2ª fase (1930–1945)</b>: poesia reflexiva e social — <b>Carlos Drummond de Andrade</b> ("No meio do caminho", <i>Sentimento do Mundo</i>), <b>Cecília Meireles</b>, <b>Vinicius de Moraes</b>; romance regionalista de 30 — <b>Graciliano Ramos</b> (<i>Vidas Secas</i>, <i>São Bernardo</i>), <b>Rachel de Queiroz</b> (<i>O Quinze</i>), <b>Jorge Amado</b> (<i>Capitães da Areia</i>), <b>José Lins do Rego</b> (<i>Menino de Engenho</i>), <b>Erico Verissimo</b>.</li><li><b>3ª fase (a partir de 1945)</b>: experimentação com a linguagem — <b>Guimarães Rosa</b> (<i>Grande Sertão: Veredas</i>, 1956), <b>Clarice Lispector</b> (<i>A Hora da Estrela</i>, 1977), <b>João Cabral de Melo Neto</b> (<i>Morte e Vida Severina</i>).</li></ul>`,
{pairs:[['Euclides da Cunha','autor pré-modernista de Os Sertões, sobre a Guerra de Canudos'],['Lima Barreto','autor de Triste Fim de Policarpo Quaresma'],['Mário de Andrade','autor de Macunaíma, "o herói sem nenhum caráter"'],['Oswald de Andrade','autor do Manifesto Antropófago (1928)'],['Graciliano Ramos','autor de Vidas Secas, sobre a família de Fabiano'],['Rachel de Queiroz','autora de O Quinze, sobre a seca de 1915'],['Carlos Drummond de Andrade','poeta de "No meio do caminho tinha uma pedra"'],['Guimarães Rosa','autor de Grande Sertão: Veredas'],['Clarice Lispector','autora de A Hora da Estrela, com a nordestina Macabéa'],['João Cabral de Melo Neto','autor do auto de Natal Morte e Vida Severina']],
 qs:[['A Semana de Arte Moderna aconteceu em:','1922, em São Paulo',['1922, no Rio de Janeiro','1930, em São Paulo','1945, em Belo Horizonte'],'Fevereiro de <b>1922</b>, no Theatro Municipal de <b>São Paulo</b>.'],['O Manifesto Antropófago propõe:','"devorar" a cultura estrangeira e transformá-la em algo brasileiro',['copiar fielmente os modelos europeus','voltar aos valores do Arcadismo','abandonar qualquer influência indígena'],'A antropofagia cultural de Oswald de Andrade (1928).'],['O romance regionalista de 1930, que denuncia a seca e a miséria no Nordeste, tem como exemplo:','Vidas Secas',['Macunaíma','Dom Casmurro','A Moreninha'],'<i>Vidas Secas</i> (1938), de Graciliano Ramos.'],['A inovação na linguagem, com neologismos e a fala do sertão, marca a obra de:','Guimarães Rosa',['Olavo Bilac','José de Alencar','Castro Alves'],'<b>Guimarães Rosa</b>, de <i>Grande Sertão: Veredas</i>.'],['Uma característica da 1ª fase modernista é:','o verso livre e a linguagem coloquial',['o soneto com rimas ricas','a idealização do indígena','o pessimismo ultrarromântico'],'Ruptura com a tradição: <b>verso livre</b>, humor e coloquialidade.']]}),
SKL('versif','Versificação e interpretação de poemas','🎼','Conte as sílabas poéticas até a última tônica; soneto tem 14 versos: dois quartetos e dois tercetos.',
`<p><b>Verso</b> é cada linha do poema; <b>estrofe</b>, o conjunto de versos. <b>Soneto</b>: 14 versos em dois <b>quartetos</b> e dois <b>tercetos</b>.</p>
<h3>Métrica</h3><p>As <b>sílabas poéticas</b> são contadas até a última sílaba tônica, juntando vogais entre palavras (elisão). <b>Redondilha menor</b>: 5 sílabas; <b>redondilha maior</b>: 7; <b>decassílabo</b>: 10; <b>alexandrino</b>: 12. Versos sem métrica fixa são <b>versos livres</b>.</p>
<h3>Rima</h3><p><b>Emparelhada</b> (AABB), <b>alternada ou cruzada</b> (ABAB), <b>interpolada ou oposta</b> (ABBA). <b>Rima rica</b>: entre classes gramaticais diferentes; <b>pobre</b>: da mesma classe. <b>Versos brancos</b>: sem rima.</p>
<h3>Eu lírico</h3><p>É a "voz" que fala no poema — não se confunde com o autor.</p>`,
{pairs:[['Soneto','poema de 14 versos: dois quartetos e dois tercetos'],['Redondilha maior','verso de 7 sílabas poéticas'],['Redondilha menor','verso de 5 sílabas poéticas'],['Decassílabo','verso de 10 sílabas poéticas'],['Alexandrino','verso de 12 sílabas poéticas'],['Verso livre','verso sem métrica regular'],['Verso branco','verso sem rima'],['Eu lírico','a voz que se expressa no poema, diferente do autor'],['Rima interpolada','esquema ABBA'],['Rima alternada','esquema ABAB']],
 qs:[['Quantos versos tem um soneto?','14',['12','10','16'],'Dois quartetos (8) + dois tercetos (6) = <b>14</b>.'],['Em "Minha terra tem palmeiras" (Mi-nha-ter-ra-tem-pal-<b>mei</b>-ras), contamos até a última tônica. O verso tem:','7 sílabas poéticas (redondilha maior)',['8 sílabas poéticas','5 sílabas poéticas','10 sílabas poéticas'],'Conta-se até "mei": 7 sílabas — <b>redondilha maior</b>.'],['O esquema de rimas ABAB é chamado de:','alternado (cruzado)',['emparelhado','interpolado','branco'],'A rima com C, B com D: <b>alternada</b>.']]})
]});

